}

solution:
function MissingNumber(nums: int[]) -> int {
  let n = nums.length();
  let total = n * (n + 1) / 2;
  let sum = 0;
  let i = 0;
  while (i < n) {
    sum += nums[i];
    i += 1;
  }
  return total - sum;
}
